#!/usr/bin/env node
/**
 * Flight Compensation Calculator
 * Calculates compensation based on EU EC 261/2004 and US DOT guidelines
 * for flight delays, cancellations, and denied boarding.
 */

// ── Constants ────────────────────────────────────────────

const EU_COMPENSATION = {
  short:  250,  // ≤ 1,500 km
  medium: 400,  // 1,500–3,500 km
  long:   600,  // > 3,500 km
};

const US_DENIED_BOARDING = {
  short_delay: { multiplier: 2, max: 775  },  // 1–2 hr domestic
  long_delay:  { multiplier: 4, max: 1550 },  // > 2 hr domestic
};

// ── Helpers ──────────────────────────────────────────────

function classifyDistance(km) {
  if (km <= 1500)  return "short";
  if (km <= 3500)  return "medium";
  return "long";
}

function distanceLabel(cls) {
  return {
    short:  "Short-haul (≤1,500 km)",
    medium: "Medium-haul (1,500–3,500 km)",
    long:   "Long-haul (>3,500 km)",
  }[cls];
}

// ── EU Compensation ──────────────────────────────────────

function calcEU(passenger, flight) {
  const distClass = classifyDistance(flight.distanceKm);

  if (!flight.airlineFault) {
    return result(passenger, false, 0, "EUR",
      "Extraordinary circumstances",
      "No compensation owed when disruption is due to extraordinary circumstances (weather, strikes, etc.).");
  }

  if (flight.disruptionType === "delay" && flight.delayHours < 3) {
    return result(passenger, false, 0, "EUR",
      "Delay under 3 hours",
      "EU regulations require a minimum 3-hour delay for compensation eligibility.");
  }

  let amount = EU_COMPENSATION[distClass];

  // 50% reduction for long-haul delays between 3-4 hours
  if (flight.disruptionType === "delay" && flight.delayHours >= 3 && flight.delayHours < 4 && distClass === "long") {
    amount *= 0.5;
  }

  if (flight.disruptionType === "downgrade") {
    const reductionMap = { short: 0.30, medium: 0.50, long: 0.75 };
    amount = passenger.ticketPrice * reductionMap[distClass];
  }

  return result(passenger, true, amount, "EUR",
    `${capitalize(flight.disruptionType)} — ${distanceLabel(distClass)}`,
    `EC 261/2004: ${distanceLabel(distClass)} flight, ${flight.disruptionType} of ${flight.delayHours}h. Compensation: €${amount.toFixed(2)} per passenger.`);
}

// ── US Compensation ──────────────────────────────────────

function calcUS(passenger, flight) {
  if (flight.disruptionType === "denied_boarding") {
    if (flight.delayHours <= 1) {
      return result(passenger, false, 0, "USD",
        "Rebooked within 1 hour",
        "No compensation required if alternate transport arrives within 1 hour.");
    }
    const tier = flight.delayHours <= 2 ? "short_delay" : "long_delay";
    const rule = US_DENIED_BOARDING[tier];
    const comp = Math.min(passenger.ticketPrice * rule.multiplier, rule.max);
    return result(passenger, true, comp, "USD",
      `Denied Boarding — ${tier.replace("_", " ")}`,
      `US DOT: Denied boarding with ${flight.delayHours}h delay. Compensation: $${comp.toFixed(2)} (up to $${rule.max} max).`);
  }

  if (["delay", "cancellation"].includes(flight.disruptionType)) {
    let estimated = 0;
    let note = "voluntary";
    if (flight.delayHours >= 3) {
      estimated = Math.min(passenger.ticketPrice * 0.5, 300);
      note = "estimated voluntary";
    }
    return result(passenger, flight.delayHours >= 3, estimated, "USD",
      `${capitalize(flight.disruptionType)} — ${note} compensation`,
      `US DOT does not mandate compensation for ${flight.disruptionType}s. Airlines may voluntarily offer vouchers/credits. Estimated: $${estimated.toFixed(2)} based on ticket price.`);
  }

  return result(passenger, false, 0, "USD", "No applicable US regulation",
    "This disruption type is not covered by current US DOT compensation rules.");
}

// ── Utilities ────────────────────────────────────────────

function result(passenger, eligible, amount, currency, reason, details) {
  return { passenger: passenger.name, eligible, amount: Math.round(amount * 100) / 100, currency, reason, details };
}

function capitalize(s) {
  return s.charAt(0).toUpperCase() + s.slice(1).replace("_", " ");
}

// ── Report Printing ──────────────────────────────────────

function printReport(flight, results, regionLabel) {
  const line = "=".repeat(70);
  const dash = "-".repeat(70);
  const distClass = classifyDistance(flight.distanceKm);

  console.log(`\n${line}`);
  console.log("        FLIGHT COMPENSATION CALCULATION REPORT");
  console.log(`        ${regionLabel}`);
  console.log(line);
  console.log(`\n  Reservation:     ${flight.reservationCode}`);
  console.log(`  Route:           ${flight.origin} → ${flight.destination}`);
  console.log(`  Scheduled Date:  ${flight.scheduledDate}`);
  console.log(`  Distance:        ${flight.distanceKm.toLocaleString()} km (${distanceLabel(distClass)})`);
  console.log(`  Disruption:      ${capitalize(flight.disruptionType)}`);
  console.log(`  Delay:           ${flight.delayHours} hours`);
  console.log(`  Regulation:      ${regionLabel}`);
  console.log(`  Airline Fault:   ${flight.airlineFault ? "Yes" : "No"}`);
  console.log(`\n${dash}`);
  console.log("  PASSENGER COMPENSATION DETAILS");
  console.log(dash);

  let total = 0;
  let cur = "USD";
  results.forEach((r, i) => {
    const status = r.eligible ? "✅ ELIGIBLE" : "❌ NOT ELIGIBLE";
    cur = r.currency;
    console.log(`\n  Passenger ${i + 1}: ${r.passenger}`);
    console.log(`    Status:        ${status}`);
    console.log(`    Compensation:  ${r.currency} ${r.amount.toFixed(2)}`);
    console.log(`    Reason:        ${r.reason}`);
    console.log(`    Details:       ${r.details}`);
    total += r.amount;
  });

  console.log(`\n${line}`);
  console.log(`  TOTAL COMPENSATION (${results.length} passengers): ${cur} ${total.toFixed(2)}`);
  console.log(line);
  return total;
}

// ══════════════════════════════════════════════════════════
// Demo: Reservation C4C633 — SEA → SAN on 2026-10-01
// ══════════════════════════════════════════════════════════

const passengers = [
  { name: "Passenger 1", ticketPrice: 320.00 },
  { name: "Passenger 2", ticketPrice: 320.00 },
];

const flight = {
  reservationCode: "C4C633",
  origin: "SEA",
  destination: "SAN",
  scheduledDate: "2026-10-01",
  distanceKm: 1790,       // SEA to SAN ≈ 1,790 km
  delayHours: 4.0,        // Example: 4-hour delay
  disruptionType: "delay", // "delay" | "cancellation" | "denied_boarding" | "downgrade"
  airlineFault: true,
};

// ── US Rules (applicable for domestic) ───────────────────
const usResults = passengers.map(p => calcUS(p, flight));
printReport(flight, usResults, "US (DOT Guidelines)");

// ── EU Rules (for comparison) ────────────────────────────
console.log("\n\n  📊 For comparison under EU EC 261/2004 rules:\n");
const euResults = passengers.map(p => calcEU(p, flight));
printReport(flight, euResults, "EU (EC 261/2004)");

// ── Export JSON Report ───────────────────────────────────
const fs = require("fs");
const report = {
  reportGenerated: new Date().toISOString(),
  flight,
  usCompensation: { results: usResults, total: usResults.reduce((s, r) => s + r.amount, 0) },
  euCompensation: { results: euResults, total: euResults.reduce((s, r) => s + r.amount, 0) },
};
fs.writeFileSync("compensation_report.json", JSON.stringify(report, null, 2));
console.log("\n\n  📄 Report exported to: compensation_report.json");
console.log("  📄 Travel certificate:  travel_certificate.html (open in browser)\n");

